-- Seed PMA Long Course 160 note content in Supabase so no Storage upload is required.
begin;

create table if not exists public.paid_note_contents (
  note_slug text primary key,
  title text not null,
  content_markdown text not null,
  updated_at timestamptz not null default now(),
  constraint paid_note_contents_slug_check check (note_slug in (
    'pma-lc160-initial-test-foundations',
    'pma-lc160-initial-test-practice-plan',
    'pma-lc160-interview-introduction',
    'pma-lc160-interview-personal-questions',
    'pma-lc160-interview-current-affairs',
    'pma-lc160-issb-group-discussion',
    'pma-lc160-issb-psychological-preparation',
    'pma-lc160-issb-leadership',
    'pma-lc160-physical-progressive-training',
    'pma-lc160-physical-test-day'
  ))
);

alter table public.paid_note_contents enable row level security;
revoke all on table public.paid_note_contents from public, anon, authenticated;

insert into public.paid_note_contents (note_slug, title, content_markdown)
values
  ('pma-lc160-initial-test-foundations', 'PMA LC 160: Initial Test Foundations', convert_from(decode('', 'base64'), 'UTF8')),
  ('pma-lc160-initial-test-practice-plan', 'PMA LC 160: Initial Test Practice Plan', convert_from(decode('', 'base64'), 'UTF8')),
  ('pma-lc160-interview-introduction', 'PMA LC 160: Interview Introduction', convert_from(decode('', 'base64'), 'UTF8')),
  ('pma-lc160-interview-personal-questions', 'PMA LC 160: Personal Interview Questions', convert_from(decode('', 'base64'), 'UTF8')),
  ('pma-lc160-interview-current-affairs', 'PMA LC 160: Current Affairs Preparation', convert_from(decode('', 'base64'), 'UTF8')),
  ('pma-lc160-issb-group-discussion', 'PMA LC 160: ISSB Group Discussion', convert_from(decode('', 'base64'), 'UTF8')),
  ('pma-lc160-issb-psychological-preparation', 'PMA LC 160: ISSB Psychological Preparation', convert_from(decode('', 'base64'), 'UTF8')),
  ('pma-lc160-issb-leadership', 'PMA LC 160: ISSB Interview and Leadership', convert_from(decode('', 'base64'), 'UTF8')),
  ('pma-lc160-physical-progressive-training', 'PMA LC 160: Progressive Physical Preparation', convert_from(decode('', 'base64'), 'UTF8')),
  ('pma-lc160-physical-test-day', 'PMA LC 160: Physical Test-Day Readiness', convert_from(decode('', 'base64'), 'UTF8'))
on conflict (note_slug) do update
set title = excluded.title,
    content_markdown = excluded.content_markdown,
    updated_at = now();

create or replace function public.get_paid_note_content(p_note_slug text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_content public.paid_note_contents%rowtype;
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;
  if p_note_slug is null or p_note_slug not in (
    'pma-lc160-initial-test-foundations',
    'pma-lc160-initial-test-practice-plan',
    'pma-lc160-interview-introduction',
    'pma-lc160-interview-personal-questions',
    'pma-lc160-interview-current-affairs',
    'pma-lc160-issb-group-discussion',
    'pma-lc160-issb-psychological-preparation',
    'pma-lc160-issb-leadership',
    'pma-lc160-physical-progressive-training',
    'pma-lc160-physical-test-day'
  ) then
    raise exception 'This paid note is not available';
  end if;
  if public.get_access_level_for_user(v_user_id) not in ('pro', 'premium')
    and not exists (
      select 1
      from public.mock_test_purchase_requests purchase
      where purchase.user_id = v_user_id
        and purchase.test_slug = p_note_slug
        and purchase.status = 'APPROVED'
    ) then
    raise exception 'An approved purchase or active Pro plan is required to view this note';
  end if;

  select * into v_content
  from public.paid_note_contents
  where note_slug = p_note_slug;
  if not found then
    raise exception 'Paid note content is not available';
  end if;

  return jsonb_build_object(
    'note_slug', v_content.note_slug,
    'title', v_content.title,
    'content_markdown', v_content.content_markdown
  );
end;
$$;

revoke all on function public.get_paid_note_content(text) from public, anon;
grant execute on function public.get_paid_note_content(text) to authenticated;

commit;
